// Port of src/llm_sim_bench/estimator.py. Python is the reference
// implementation; web/test/golden.json (generated by `llmsim export-web`)
// keeps the two in sync. Keep the formulas and their order identical.

const GB = 1e9;

export function ramBandwidthGbps(kind, channels = 2) {
  const m = /^(?:l?pddr|ddr)\d-(\d+)$/.exec(kind.trim().toLowerCase());
  if (!m) throw new Error(`Unrecognized RAM kind ${kind}; expected e.g. 'ddr5-5600'`);
  return (Number(m[1]) * 8 * channels) / 1000;
}

export function kvBytesPerToken(model, kvBits = 16) {
  return (2 * model.n_layers * model.n_kv_heads * model.head_dim * kvBits) / 8;
}

export function activeB(model) {
  return model.active_params_b || model.params_b;
}

export const BACKENDS = ["cuda", "metal", "rocm", "vulkan", "sycl", "cpu"];

// Efficiency field prefix for a backend ("cuda" predates the others as "gpu").
export function backendPrefix(backend) {
  if (!BACKENDS.includes(backend)) throw new Error(`Unknown backend ${backend}`);
  return backend === "cuda" ? "gpu" : backend;
}

function forBackend(eff, backend) {
  const p = backendPrefix(backend);
  return [eff[`${p}_bandwidth`], eff[`${p}_compute`], eff[`${p}_layer_overhead_us`] / 1e6];
}

// Build a system from the JSON spec shared with export.py:
//   {kind: "pc", cpu, ram_gb, ram_bandwidth_gbps, gpus: [names], backend?: override}
//   {kind: "unified", chip, memory_gb}
export function buildSystem(spec, presets) {
  const find = (list, name, what) => {
    const hit = list.find((x) => x.name === name);
    if (!hit) throw new Error(`Unknown ${what} preset ${name}`);
    return hit;
  };
  if (spec.kind === "unified" || spec.kind === "apple") {
    const found = find(presets.unified, spec.chip, "unified-memory chip");
    const chip = spec.backend ? { ...found, backend: spec.backend } : found;
    return {
      cpu: { name: `${chip.name}-cpu`, cores: chip.cpu_cores, fp32_tflops: chip.cpu_tflops },
      ram: { size_gb: spec.memory_gb, bandwidth_gbps: chip.bandwidth_gbps },
      gpus: [{
        name: chip.name, vram_gb: spec.memory_gb, bandwidth_gbps: chip.bandwidth_gbps,
        fp16_tflops: chip.gpu_tflops, backend: chip.backend, vendor: chip.vendor,
      }],
      unified: true,
      gpu_fraction: chip.gpu_fraction,
    };
  }
  const gpus = spec.gpus.map((g) => find(presets.gpus, g, "GPU"));
  return {
    cpu: find(presets.cpus, spec.cpu, "CPU"),
    ram: { size_gb: spec.ram_gb, bandwidth_gbps: spec.ram_bandwidth_gbps },
    gpus: spec.backend ? gpus.map((g) => ({ ...g, backend: spec.backend })) : gpus,
    unified: false,
  };
}

export function estimate(system, model, quant, context, kvBits, eff, quantBpw) {
  if (!(quant in quantBpw)) throw new Error(`Unknown quant ${quant}`);
  const notes = [];
  if (context > model.max_context) {
    notes.push(`context ${context} exceeds model max ${model.max_context}`);
  }

  const weights = (model.params_b * 1e9 * quantBpw[quant]) / 8;
  const kvTok = kvBytesPerToken(model, kvBits);
  const kvTotal = kvTok * context;
  const layerW = weights / model.n_layers;
  const layerKv = kvTotal / model.n_layers;

  const placements = [];
  let remaining = model.n_layers;
  let gpuUsedGb = 0;
  for (const gpu of system.gpus) {
    const frac = system.gpu_fraction || eff.unified_gpu_fraction;
    const vram = system.unified ? system.ram.size_gb * frac : gpu.vram_gb;
    const usable = Math.max(0, vram - eff.vram_reserve_gb) * GB;
    const n = Math.min(remaining, Math.floor(usable / (layerW + layerKv)));
    if (n > 0) {
      const [bwEff, cEff, layerS] = forBackend(eff, gpu.backend || "cuda");
      placements.push({
        device: gpu.name, layers: n,
        weights_gb: (n * layerW) / GB, kv_gb: (n * layerKv) / GB,
        bandwidth_gbps: gpu.bandwidth_gbps * bwEff, tflops: gpu.fp16_tflops * cEff,
        is_gpu: true, overhead_s: n * layerS,
      });
      remaining -= n;
      gpuUsedGb += (n * (layerW + layerKv)) / GB;
    }
  }

  let fits = true;
  let ramNeededGb = 0;
  let ramFreeGb = system.ram.size_gb - eff.ram_reserve_gb;
  if (system.unified) ramFreeGb -= gpuUsedGb;
  if (remaining) {
    const cpuGb = (remaining * (layerW + layerKv)) / GB;
    const [bwEff, cEff, layerS] = forBackend(eff, "cpu");
    placements.push({
      device: `cpu:${system.cpu.name}`, layers: remaining,
      weights_gb: (remaining * layerW) / GB, kv_gb: (remaining * layerKv) / GB,
      bandwidth_gbps: system.ram.bandwidth_gbps * bwEff,
      tflops: system.cpu.fp32_tflops * cEff, is_gpu: false, overhead_s: remaining * layerS,
    });
    ramNeededGb = cpuGb;
    if (cpuGb > ramFreeGb) {
      fits = false;
      notes.push(`needs ${cpuGb.toFixed(1)} GB in RAM but only ${ramFreeGb.toFixed(1)} GB ` +
                 "is free; it would page to disk");
    }
    if (system.gpus.length) notes.push(`${remaining}/${model.n_layers} layers offloaded to CPU`);
  }

  const activeRatio = activeB(model) / model.params_b;
  let baseTime = 0;
  let prefillTime = 0;
  const kvTerms = [];
  for (const p of placements) {
    const frac = p.layers / model.n_layers;
    const bw = p.bandwidth_gbps * GB;
    baseTime += (p.weights_gb * GB * activeRatio) / bw + p.overhead_s;
    kvTerms.push([kvTok * frac, bw]);
    prefillTime += (2 * activeB(model) * 1e9 * frac) / (p.tflops * 1e12);
  }

  const decodeTpsAt = (filled) => {
    let t = baseTime;
    for (const [b, bw] of kvTerms) t += (b * filled) / bw;
    return t > 0 ? 1 / t : Infinity;
  };

  return {
    model, quant, context,
    weights_gb: weights / GB, kv_gb: kvTotal / GB,
    placements, fits, notes,
    prefill_tps: 1 / prefillTime,
    decode_tps_empty: decodeTpsAt(0),
    decode_tps_full: decodeTpsAt(context),
    decodeTpsAt,
    // Extra fields for the UI (not in the Python Estimate).
    gpu_used_gb: gpuUsedGb, ram_needed_gb: ramNeededGb, ram_free_gb: ramFreeGb,
  };
}
